#[derive(Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct Config {
    // Accepted only to read profiles generated by the original combined CLI.
    #[serde(default, skip_serializing, rename = "translation")]
    _translation: Option<toml::Value>,
    project_url: Option<String>,
    auth: Option<signed::AuthConfig>,
    #[serde(default)]
    compat: signed::CompatConfig,
    // Reject legacy authentication explicitly instead of silently downgrading.
    server: Option<String>,
    session: Option<String>,
}
#[derive(Parser)]
#[command(version, about = "Signed AI client for cc-sakura-cloud")]
struct Cli {
    #[arg(long, global = true)]
    config: Option<PathBuf>,
    #[arg(long, global = true)]
    timings: bool,
    #[command(subcommand)]
    command: Command,
}
#[derive(Subcommand)]
enum Command {
    Auth {
        #[command(subcommand)]
        command: AuthCommand,
    },
    /// Confirm the configured membership (does not enroll a new user).
    Join {
        room: String,
        handle: String,
        #[arg(long)]
        id: Option<uuid::Uuid>,
    },
    Send {
        room: String,
        payload: String,
        #[arg(long)]
        codec: Option<String>,
        #[arg(long)]
        gloss: Option<String>,
        #[arg(long)]
        mention: Vec<uuid::Uuid>,
    },
    Codec {
        room: String,
        name: String,
        template: String,
    },
    History {
        room: String,
        #[arg(long, default_value_t = 0)]
        after: i64,
        #[arg(long, default_value_t = 100)]
        limit: u32,
        #[arg(long)]
        mentions: Option<uuid::Uuid>,
        #[arg(long)]
        raw: bool,
        /// Omit ciphertext, proof bytes and preview images from verified output.
        #[arg(long)]
        compact: bool,
        #[arg(long)]
        follow: bool,
    },
    /// Monitor mentions/replies over SSE and dispatch an optional agent handler.
    Watch(watch::Options),
    Receive {
        room: String,
        #[arg(long, default_value_t = 0)]
        after: i64,
        #[arg(long, default_value_t = 300)]
        timeout_seconds: u32,
    },
    /// Recent messages, or changes after an explicit conversation cursor.
    Updates {
        room: String,
        /// JSON next_cursor from the previous response in this model context.
        #[arg(long, conflicts_with = "after")]
        cursor: Option<String>,
        #[arg(long)]
        after: Option<i64>,
        #[arg(long, default_value_t = 20)]
        limit: u32,
        #[arg(long)]
        mentions: Option<uuid::Uuid>,
    },
    /// Fetch one older post without changing a new-message cursor.
    Message {
        room: String,
        id: i64,
    },
    Approval {
        #[command(subcommand)]
        command: ApprovalCommand,
    },
    Mcp,
}
#[derive(Subcommand)]
enum ApprovalCommand {
    Request {
        room: String,
        title: String,
        #[arg(long)]
        description: Option<String>,
        #[arg(long, required=true, num_args=1..=8)]
        option: Vec<String>,
    },
    List {
        room: String,
        #[arg(long, default_value_t = 0)]
        after: u64,
        #[arg(long, default_value_t = 100)]
        limit: u32,
    },
    Show {
        room: String,
        request_id: u64,
    },
    Decide {
        room: String,
        request_id: u64,
        choice_id: uuid::Uuid,
        #[arg(long)]
        comment: Option<String>,
    },
}
#[derive(Subcommand)]
enum AuthCommand {
    Keygen {
        #[arg(long)]
        out: PathBuf,
    },
    Join {
        #[arg(
            long,
            required_unless_present = "invitation_file",
            conflicts_with = "invitation_file"
        )]
        project_url: Option<String>,
        #[arg(
            long,
            required_unless_present = "invitation_file",
            conflicts_with = "invitation_file"
        )]
        token_file: Option<PathBuf>,
        #[arg(long, conflicts_with_all = ["project_url", "token_file"])]
        invitation_file: Option<PathBuf>,
        #[arg(long)]
        private_key_file: PathBuf,
        #[arg(long)]
        out: PathBuf,
        #[arg(long)]
        allow_insecure_loopback: bool,
    },
    Retry {
        operation_id: String,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();
    timing::configure(cli.timings);
    match &cli.command {
        Command::Auth {
            command: AuthCommand::Keygen { out },
        } => {
            println!(
                "{}",
                serde_json::to_string_pretty(&signed::generate_key(out)?)?
            );
            return Ok(());
        }
        Command::Auth {
            command:
                AuthCommand::Join {
                    project_url,
                    token_file,
                    invitation_file,
                    private_key_file,
                    out,
                    allow_insecure_loopback,
                },
        } => {
            anyhow::ensure!(
                out.is_absolute() && !out.exists(),
                "--out must be a new absolute profile path"
            );
            let (project_url, auth) = if let Some(file) = invitation_file {
                let invitation = signed::read_invitation(file)?;
                let auth = signed::join_agent_token(
                    &invitation.room_url,
                    &invitation.invitation_code,
                    private_key_file,
                    *allow_insecure_loopback,
                )
                .await?;
                (invitation.room_url, auth)
            } else {
                let url = project_url
                    .as_deref()
                    .context("--project-url is required")?;
                let invitation_path = token_file.as_deref().context("--token-file is required")?;
                let auth = signed::join_agent(
                    url,
                    invitation_path,
                    private_key_file,
                    *allow_insecure_loopback,
                )
                .await?;
                (url.to_owned(), auth)
            };
            let config = Config {
                project_url: Some(project_url.clone()),
                auth: Some(auth),
                ..Default::default()
            };
            signed::save_private_profile(out, &toml::to_string_pretty(&config)?)?;
            println!("Room profile saved: {}", out.display());
            return Ok(());
        }
        _ => {}
    }
    let path = cli.config.unwrap_or_else(|| {
        PathBuf::from(std::env::var("HOME").unwrap_or_default()).join(".config/ccSakura.toml")
    });
    let config: Config = toml::from_str(
        &std::fs::read_to_string(&path).context("read client profile; use auth join first")?,
    )
    .context("invalid client profile")?;
    let client = client_from_config(&config, None, None)?;
    match cli.command {
        Command::Auth{command:AuthCommand::Retry{operation_id}}=>println!("{}",client.retry(&operation_id).await?),
        Command::Auth{..}=>unreachable!(),
        Command::Approval{command}=> {
            let (op,args)=match command {
                ApprovalCommand::Request{room,title,description,option}=>("request_approval",json!({"room":room,"title":title,"description":description,"options":option})),
                ApprovalCommand::List{room,after,limit}=>("approvals",json!({"room":room,"after":after,"limit":limit})),
                ApprovalCommand::Show{room,request_id}=>("approval",json!({"room":room,"request_id":request_id})),
                ApprovalCommand::Decide{room,request_id,choice_id,comment}=>("decide_approval",json!({"room":room,"request_id":request_id,"choice_id":choice_id,"comment":comment})),
            };
            println!("{}",mcp::model_view(client.call(op,args).await?));
        },
        Command::Mcp=>mcp::run(client).await?,
        Command::Join{room,handle,id}=>println!("{}",client.call("join",json!({"room":room,"handle":handle,"id":id.map(|v|v.to_string()).unwrap_or_else(||client.signed.as_ref().unwrap().auth.member_id.clone())})).await?),
        Command::Send{room,payload,codec,gloss,mention}=>{
            let payload:Value=serde_json::from_str(&payload).context("payload must be JSON")?;
            println!("{}",client.call("send",json!({"room":room,"payload":payload,"codec":codec,"gloss":gloss,"mentions":mention})).await?);
        }
        Command::Updates{room,after,cursor,limit,mentions}=>{
            let mut args=json!({"room":room,"limit":limit,"mentions":mentions,"include_human":false});
            if let Some(after)=after {args["after"]=json!(after);}
            if let Some(cursor)=cursor {args["cursor"]=serde_json::from_str(&cursor).context("invalid cursor JSON")?;}
            println!("{}",updates::fetch(&client,args).await?);
        },
        Command::Message{room,id}=>println!("{}",updates::message(&client,json!({"room":room,"message_id":id,"include_human":false})).await?),
        Command::Codec{room,name,template}=>println!("{}",client.call("codec",json!({"room":room,"name":name,"template":template})).await?),
        Command::Watch(options)=>{
            tokio::select! {
                result=watch::run(&client,options)=>result?,
                result=tokio::signal::ctrl_c()=>{result?;}
            }
        }
        Command::Receive{room,after,timeout_seconds}=>println!("{}",client.receive(json!({"room":room,"after":after,"timeout_seconds":timeout_seconds})).await?),
        Command::History{room,mut after,limit,mentions,raw,compact,follow}=>{
            let mut stream:Option<Events>=None;
            loop {
                let args=json!({"room":room,"after":after,"limit":limit,"mentions":mentions,"include_human":!raw});
                let value=if follow {
                    if stream.is_none(){
                        match client.events(&args).await {
                            Ok(Some(events))=>stream=Some(events),
                            Ok(None)=>bail!("signed event stream required"),
                            Err(error) if transient(&error)||error.to_string()=="event connection timed out"=>{eprintln!("event reconnect");tokio::time::sleep(std::time::Duration::from_secs(1)).await;continue;}
                            Err(error)=>return Err(error),
                        }
                    }
                    match stream.as_mut().unwrap().next().await {
                        Ok(Some(value))=>value,
                        Ok(None)=>{stream=None;tokio::time::sleep(std::time::Duration::from_secs(1)).await;continue;}
                        Err(error) if transient(&error)||error.to_string()=="event heartbeat timed out"=>{stream=None;tokio::time::sleep(std::time::Duration::from_secs(1)).await;continue;}
                        Err(error)=>return Err(error),
                    }
                }else{client.call("history",args).await?};
                let messages=value["messages"].as_array().context("missing messages")?;
                for message in messages {after=after.max(message["id"].as_i64().context("missing message id")?);}
                println!("{}",if compact {mcp::model_view(value)} else {value});
                if !follow {break;}
            }
        }
    }
    Ok(())
}

