#[derive(Clone)]
pub struct Client {
    http: reqwest::Client,
    signed: Option<std::sync::Arc<signed::SignedClient>>,
}
pub struct Events {
    response: reqwest::Response,
    buffer: Vec<u8>,
    verifier: Option<(std::sync::Arc<signed::SignedClient>, reqwest::Client)>,
}
impl Events {
    async fn next(&mut self) -> Result<Option<Value>> {
        timing::measure("sse.wait_and_verify", "subscribe", self.next_inner()).await
    }
    async fn next_inner(&mut self) -> Result<Option<Value>> {
        loop {
            let boundary = self
                .buffer
                .windows(2)
                .position(|w| w == b"\n\n")
                .map(|end| (end, 2))
                .or_else(|| {
                    self.buffer
                        .windows(4)
                        .position(|w| w == b"\r\n\r\n")
                        .map(|end| (end, 4))
                });
            if let Some((end, separator)) = boundary {
                let frame: Vec<u8> = self.buffer.drain(..end + separator).collect();
                let text = std::str::from_utf8(&frame).context("invalid event UTF-8")?;
                let data = text
                    .lines()
                    .filter_map(|line| line.strip_prefix("data:").map(str::trim_start))
                    .collect::<Vec<_>>()
                    .join("\n");
                if !data.is_empty() {
                    let value = serde_json::from_str(&data)?;
                    let value = if let Some((client, http)) = &self.verifier {
                        client.verify_history(http, value).await?
                    } else {
                        value
                    };
                    return Ok(Some(value));
                }
                continue;
            }
            match tokio::time::timeout(std::time::Duration::from_secs(45), self.response.chunk())
                .await
                .context("event heartbeat timed out")??
            {
                Some(chunk) => {
                    self.buffer.extend_from_slice(&chunk);
                    let limit = if self.verifier.is_some() {
                        8 * 1024 * 1024
                    } else {
                        256 * 1024 * 1024
                    };
                    if self.buffer.len() > limit {
                        bail!("event exceeds the client size limit");
                    }
                }
                None => return Ok(None),
            }
        }
    }
}
fn transient(error: &anyhow::Error) -> bool {
    error.downcast_ref::<reqwest::Error>().is_some_and(|e| {
        if let Some(status) = e.status() {
            return status.is_server_error();
        }
        e.is_connect() || e.is_request() || e.is_timeout() || e.is_body()
    })
}
impl Client {
    // A dedicated client has no whole-response timeout: SSE is intentionally long-lived.
    async fn events(&self, args: &Value) -> Result<Option<Events>> {
        let http = reqwest::Client::builder()
            .connect_timeout(std::time::Duration::from_secs(10))
            .redirect(reqwest::redirect::Policy::none())
            .build()?;
        let signed = self
            .signed
            .as_ref()
            .context("signed authentication required")?;
        let response = tokio::time::timeout(
            std::time::Duration::from_secs(15),
            signed.events(&http, args),
        )
        .await
        .context("event connection timed out")??;
        Ok(Some(Events {
            response,
            buffer: Vec::new(),
            verifier: Some((signed.clone(), self.http.clone())),
        }))
    }

    async fn receive(&self, mut args: Value) -> Result<Value> {
        let deadline = tokio::time::Instant::now()
            + std::time::Duration::from_secs(
                args["timeout_seconds"].as_u64().unwrap_or(300).min(300),
            );
        let mut delay = 1;
        loop {
            let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
            args["timeout_seconds"] = json!(remaining.as_secs().max(1));
            match self.call("receive", args.clone()).await {
                Ok(value) => return Ok(value),
                Err(error) => {
                    if !transient(&error) || tokio::time::Instant::now() >= deadline {
                        return Err(error);
                    }
                    eprintln!("receive reconnect: {error}");
                    tokio::time::sleep_until(
                        (tokio::time::Instant::now() + std::time::Duration::from_secs(delay))
                            .min(deadline),
                    )
                    .await;
                    delay = (delay * 2).min(10);
                }
            }
        }
    }
    async fn retry(&self, operation_id: &str) -> Result<Value> {
        self.signed
            .as_ref()
            .context("retry requires signed authentication")?
            .retry(&self.http, operation_id)
            .await
    }
    async fn call(&self, operation: &str, args: Value) -> Result<Value> {
        self.signed
            .as_ref()
            .context("signed authentication required")?
            .call(&self.http, operation, args)
            .await
    }
}

fn client_from_config(
    config: &Config,
    server: Option<String>,
    session: Option<String>,
) -> Result<Client> {
    anyhow::ensure!(
        config.auth.is_some() && config.project_url.is_some(),
        "project_url and signed auth are required"
    );
    let signed = match (&config.auth, &config.project_url) {
        (Some(auth), Some(url)) => {
            if config.session.is_some()
                || session.is_some()
                || server.is_some()
                || config.server.is_some()
            {
                bail!(
                    "signed authentication cannot be combined with server/session overrides; use project_url"
                );
            }
            Some(std::sync::Arc::new(signed::SignedClient::new(
                url,
                auth.clone(),
                config.compat.clone(),
            )?))
        }
        (None, None) => None,
        _ => bail!("project_url and auth must be configured together"),
    };
    let mut http = reqwest::Client::builder().timeout(std::time::Duration::from_secs(30));
    if signed.is_some() {
        http = http.redirect(reqwest::redirect::Policy::none());
    }
    Ok(Client {
        http: http.build()?,
        signed,
    })
}

#[cfg(test)]
mod cli_tests {
    use super::*;
    #[test]
    fn invitation_file_is_an_alternative_to_the_legacy_join_arguments() {
        let common = [
            "cc-sakura",
            "auth",
            "join",
            "--private-key-file",
            "/tmp/agent.key",
            "--out",
            "/tmp/room.toml",
        ];
        let parse =
            |extra: &[&str]| Cli::try_parse_from(common.into_iter().chain(extra.iter().copied()));
        assert!(parse(&["--invitation-file", "/tmp/invite.json"]).is_ok());
        assert!(
            parse(&[
                "--project-url",
                "https://example.com/owner/room",
                "--token-file",
                "/tmp/token.txt"
            ])
            .is_ok()
        );
        assert!(parse(&[]).is_err());
        assert!(parse(&["--project-url", "https://example.com/owner/room"]).is_err());
        assert!(
            parse(&[
                "--invitation-file",
                "/tmp/invite.json",
                "--token-file",
                "/tmp/token.txt"
            ])
            .is_err()
        );
        assert!(
            parse(&[
                "--invitation-file",
                "/tmp/invite.json",
                "--project-url",
                "https://example.com/owner/room"
            ])
            .is_err()
        );
    }
}
